// Check for existing crafted tools, prior lessons, and docs on the crafted-tool code format before creating cache_echo
async function tryDir(p) {
  try { return await workspace.readdir(p); } catch (e) { return 'ERR ' + String(e && (e.message || e)); }
}
const existing = await workspace.listTools();
console.log('crafted tools:', JSON.stringify(existing, null, 2));
const hits = await workspace.searchMemory('createTool crafted tool code args signature');
console.log('memory hits:', hits);
const root = await tryDir('.');
console.log('root:', JSON.stringify(root));
const docs = await tryDir('docs');
console.log('docs:', JSON.stringify(docs));
const wdocs = await tryDir('/workspace/docs');
console.log('/workspace/docs:', JSON.stringify(wdocs));
return { existing, hits, root, docs };

// Search the workspace VFS roots for any spec describing how crafted-tool code is invoked
async function tryDir(p) { try { return await workspace.readdir(p); } catch (e) { return 'ERR ' + String(e && (e.message || e)); } }
const dirs = {};
for (const d of ['sandbox', 'context', 'etc', 'opt']) {
  dirs[d] = await tryDir(d);
  console.log(d + ':', JSON.stringify(dirs[d]));
}
let out = await workspace.exec('grep -ril "createtool" /sandbox /context /etc /opt 2>/dev/null | head -20; echo ---; find /sandbox /context /etc /opt -maxdepth 3 -iname "*spec*" 2>/dev/null | head -20');
console.log('grep/find:', typeof out === 'string' ? out : JSON.stringify(out));
return { dirs, out };

// Save crafted tool cache_echo via workspace.createTool(name, description, code)
const name = 'cache_echo';
const description = 'Echo: takes a {text} argument and returns that same text unchanged.';
const code = [
  '// cache_echo - return the text argument it was given, unchanged.',
  'const echo = (a) => (a && typeof a === "object" && "text" in a) ? a.text : a;',
  'if (typeof module !== "undefined" && module) {',
  '  module.exports = async function cache_echo(a) { return echo(a); };',
  '}',
  'return echo(typeof args !== "undefined" ? args : undefined);'
].join('\n');
const res = await workspace.createTool(name, description, code);
console.log('createTool result:', JSON.stringify(res));
if (res && res.ok) {
  const note = await workspace.saveNote(
    'Crafted tool cache_echo was saved via workspace.createTool(name, description, code) - three positional string args per the declaration. ' +
    'Accepted code shape: top-level program reading `args` (returns args.text), with a defensive module.exports assignment in case the host loads crafted-tool code as a module. ' +
    'Tool NOT yet invoked; it becomes callable as tools.cache_echo on the next execute_tools call.'
  );
  console.log('note saved:', note);
}
return res;

// Retry saving cache_echo as a proper module: named async function + default export
const name = 'cache_echo';
const description = 'Echo: takes a {text} argument and returns that same text unchanged.';
const code = [
  '// cache_echo - returns the text argument it was given, unchanged.',
  'async function cache_echo(args) {',
  '  return (args && typeof args === "object" && "text" in args) ? args.text : args;',
  '}',
  'export default cache_echo;'
].join('\n');
const res = await workspace.createTool(name, description, code);
console.log('createTool result:', JSON.stringify(res));
return res;
